// Category A — the between-items drop position line. When reorder is wired onto a draggable
// collection (GridList/Table/ListBox…) through dragAndDropHooks, the consumer renders this
// inside useDragAndDrop({ renderDropIndicator }). Behavior borrowed from
// react-aria-components, look owned here.
import { DropIndicator as AriaDropIndicator } from "react-aria-components";
import type { DropIndicatorProps as AriaDropIndicatorProps } from "react-aria-components";
import type { Ref } from "react";
import "./DropIndicator.css";

export interface DropIndicatorProps extends Omit<AriaDropIndicatorProps, "className"> {
  /** Additional class. sd-drop-indicator is always retained. */
  className?: string;
  /** Passed to the underlying DOM node. */
  ref?: Ref<HTMLElement>;
}

export function DropIndicator({ className, ref, ...props }: DropIndicatorProps) {
  return (
    <AriaDropIndicator
      {...props}
      ref={ref}
      className={className ? `sd-drop-indicator ${className}` : "sd-drop-indicator"}
    />
  );
}

.sd-drop-indicator {
  height: var(--sd-drop-indicator-height);
  margin-block: var(--sd-drop-indicator-margin-block);
  background: transparent;
  border-radius: var(--sd-drop-indicator-radius);
  corner-shape: round;
  outline: none;
}

.sd-drop-indicator[data-drop-target] {
  background: var(--sd-drop-indicator-background-active);
}
